<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Cetak Kartu <?= html_escape($header['no_transaksi']) ?></title><style>body{font:13px Arial;margin:20px}.box{max-width:850px;margin:auto}.preview{border:1px dashed #777;padding:20px;margin:15px 0;min-height:100px}.line{white-space:nowrap}.form{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.form input{padding:8px;width:100%;box-sizing:border-box}.btn{padding:9px 14px;border:0;border-radius:4px;cursor:pointer;background:#1677ff;color:#fff}@media print{.no-print{display:none}.preview{border:0;position:absolute;left:var(--x);top:var(--y);margin:0;padding:0}}</style></head><body><div class="box"><div class="no-print"><h3>Cetak ke Kartu Pembayaran</h3><p><?= html_escape($header['no_transaksi'].' - '.$header['nama_siswa']) ?></p><div class="form"><label>Baris<input id="baris" type="number" min="1" value="1"></label><label>Posisi X (mm)<input id="x" type="number" step="0.1" value="<?= html_escape(($format&&$format['pengaturan_json'])?(json_decode($format['pengaturan_json'],true)['posisi_x']??10):10) ?>"></label><label>Posisi Y (mm)<input id="y" type="number" step="0.1" value="<?= html_escape(($format&&$format['pengaturan_json'])?(json_decode($format['pengaturan_json'],true)['posisi_y']??10):10) ?>"></label></div><p><button class="btn" onclick="doPrint(false)">Uji Cetak</button> <button class="btn" onclick="doPrint(true)">Cetak & Tandai Digunakan</button></p></div><div id="preview" class="preview"><div class="line"><strong id="barisText">01</strong> | <?= html_escape($header['tanggal_transaksi']) ?> | <?= html_escape(implode(' + ',array_unique(array_column($detail,'nama_tagihan')))) ?> | <?= number_format($header['total_pembayaran'],0,',','.') ?> | <?= html_escape(strtoupper(substr($header['nama_user'],0,2))) ?></div></div></div><script src="<?= base_url('assets/js/jquery-3.7.1.min.js') ?>"></script><script>function update(){document.documentElement.style.setProperty('--x',$('#x').val()+'mm');document.documentElement.style.setProperty('--y',$('#y').val()+'mm');$('#barisText').text(String($('#baris').val()).padStart(2,'0'))}$('input').on('input',update);update();function doPrint(save){update();if(!save)return window.print();$.post('<?= base_url('transaksi/pembayaran/catat_cetak_kartu') ?>',{id:<?= (int)$header['id'] ?>,nomor_baris:$('#baris').val(),posisi_x:$('#x').val(),posisi_y:$('#y').val()},r=>{alert(r.message);if(r.result==='true')window.print()},'json')}</script></body></html>
